var practiceSession=null,practiceClock=null,practiceTimer=0,practiceFrame=0,practiceFeedback=null,practiceLastEvent=null,practiceEventAt=0,practiceMotionAt=0,practiceElapsed=0,practiceHistory={comeback:[],protect:[]},practiceRecorded=false,practiceReturnFocus=null;
const practiceLabels={press:'전방 압박',balanced:'균형 운영',counter:'빠른 역습'};
function practiceText(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function practicePlaying(){return !!practiceSession&&F.running(practiceSession.match)&&!practiceSession.match.paused;}
function stopPracticeMotion(){if(practicePlaying())practiceElapsed+=performance.now()-practiceMotionAt;}
function openPractice(id='comeback'){
 const dialog=$('practice-dialog');if(!dialog||dialog.open)return;
 pauseForPlanning();clearMatchFeedback();save();render();practiceReturnFocus=document.activeElement;
 practiceHistory=loadPracticeHistory();practiceSession=Practice.create(id);practiceRecorded=false;practiceLastEvent=null;practiceElapsed=0;
 practiceClock=MatchFlow.createClock();practiceFeedback=Feedback.create({vibrate:typeof navigator.vibrate==='function'?pattern=>navigator.vibrate(pattern):null,visible:()=>!document.hidden,active:()=>dialog.open&&navigator.userActivation?.hasBeenActive!==false,now:()=>performance.now(),haptics:mediaPrefs.haptics});
 dialog.innerHTML=practiceMarkup();dialog.showModal();renderPractice();renderCoachGuide();$('practice-title').setAttribute('tabindex','-1');$('practice-title').focus({preventScroll:true});
 practiceTimer=setInterval(()=>{if(!dialog.open)return;const active=practicePlaying()&&!document.hidden;if(!practiceClock.due(performance.now(),active,playbackPrefs.speed))return;const events=MatchFlow.step(practiceSession.match,{coachPause65:false});presentPracticeEvents(events);renderPractice();},100);
 function animatePractice(){if(!dialog.open)return;drawPractice();practiceFrame=requestAnimationFrame(animatePractice);}animatePractice();
}
function closePractice(){const dialog=$('practice-dialog');if(!dialog?.open)return;dialog.close();}
function cleanupPractice(){clearInterval(practiceTimer);cancelAnimationFrame(practiceFrame);practiceTimer=practiceFrame=0;practiceFeedback?.cancel();practiceSession=null;renderCoachGuide();if(practiceReturnFocus?.isConnected)practiceReturnFocus.focus();}
function practiceMarkup(){const ownClub=S.club(S.own),opponent=S.club('falkenruh');return '<div class="practice-shell"><header class="practice-header"><div><h1 id="practice-title">전술 연습</h1></div><button class="practice-close" data-practice="close" aria-label="작전 연습 닫기">×</button></header><p id="practice-description" class="practice-safe">시즌에 영향을 주지 않는 연습 경기</p><div class="practice-scenarios" role="group" aria-label="작전 연습 선택">'+Practice.scenarios.map(s=>'<button data-practice-scenario="'+s.id+'" aria-pressed="false">'+practiceText(s.id==='comeback'?'역전 연습':'리드 지키기')+'<small>'+s.startMinute+'분부터</small></button>').join('')+'</div><div class="practice-story"><span id="practice-objective"></span><p id="practice-coach"></p></div><div class="practice-layout"><section class="practice-match"><div class="practice-score" aria-label="연습 경기 점수"><span>'+practiceText(ownClub.short)+'<small>당신의 팀</small></span><div><span id="practice-minute"></span><strong id="practice-score-value"></strong></div><span>'+practiceText(opponent.short)+'<small>이번 상대</small></span></div><div class="practice-pitch"><canvas id="practice-field" aria-label="연습 경기 선수와 공 움직임"></canvas><div id="practice-impact" role="status" aria-live="polite" hidden></div></div><div class="practice-progress"><span id="practice-status"></span><span id="practice-remaining"></span></div><div id="practice-commentary" class="practice-commentary" aria-live="polite"></div><div id="practice-events" class="practice-events"></div></section><section class="practice-decisions"><div class="practice-choice-heading"><h2>전술 지시</h2><p>전술을 선택한 뒤 경기를 재개하세요.</p></div><div class="practice-tactics" role="group" aria-label="연습 전술">'+Object.entries(practiceLabels).map(([id,label])=>'<button data-practice-tactic="'+id+'" aria-pressed="false"><strong>'+label+'</strong><small>'+({press:'기회 ↑ · 체력 소모 ↑',balanced:'공격과 수비의 균형',counter:'빠른 발로 뒷공간 침투'}[id])+'</small><span id="practice-rate-'+id+'"></span></button>').join('')+'</div><p class="practice-rate-note">남은 시간의 기회 비교 · 우리 : 상대 / 평균 체력 소모</p><div id="practice-subs" class="practice-sub-panel"></div><div class="practice-feel"><button id="practice-sound" data-practice="sound"></button><button id="practice-haptic" data-practice="haptic"></button></div><p id="practice-error" role="alert" hidden></p></section></div><section id="practice-result" class="practice-result" tabindex="-1" hidden></section><div id="practice-run-controls" class="practice-run-controls"><button id="practice-play" class="primary" data-practice="play"></button><button id="practice-five" class="secondary" data-practice="five">5분 진행</button></div><div id="practice-exit" class="practice-exit"><button class="secondary" data-practice="close">연습 종료</button><span></span></div></div>';}
function renderPractice(){
 if(!practiceSession||!$('practice-dialog').open)return;const m=practiceSession.match,r=Practice.read(practiceSession),done=m.phase==='full';
 $('practice-title').textContent='전술 연습';
 $('practice-objective').textContent=practiceSession.id==='comeback'?'목표 · 무승부 이상':'목표 · 리드 유지';$('practice-coach').textContent=practiceSession.id==='comeback'?'75분부터 15분간 진행 · 전술 변경과 교체를 연습합니다.':'80분부터 10분간 진행 · 선수 체력을 확인하며 리드를 지키세요.';
 document.querySelectorAll('[data-practice-scenario]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.practiceScenario===practiceSession.id));
 $('practice-minute').textContent=done?'경기 종료':m.minute+'′';$('practice-score-value').textContent=m.score[0]+' : '+m.score[1];
 $('practice-status').textContent=done?'연습 종료':m.paused?'작전 타임 · '+practiceLabels[m.tactic]:'경기 진행 · '+practiceLabels[m.tactic];$('practice-remaining').textContent='남은 '+r.remainingMinutes+'분';
 $('practice-run-controls').hidden=done;$('practice-exit').hidden=done;
 $('practice-play').textContent=done?'다시 연습':m.paused?'경기 재개':'일시 정지';$('practice-five').disabled=done;
 document.querySelectorAll('[data-practice-tactic]').forEach(b=>{b.disabled=done;b.setAttribute('aria-pressed',m.tactic===b.dataset.practiceTactic);});
 for(const id of Object.keys(practiceLabels)){const preview=practicePreview(m,id);$('practice-rate-'+id).textContent=done?'연습 종료':'기회 '+preview.chances.map(n=>n.toFixed(1)).join(' : ')+' · 체력 −'+preview.averageCost.toFixed(1);}
 const latest=m.logs.filter(x=>x.minute>=r.startMinute&&['goal','chance','shot','sub','tactic'].includes(x.type)).at(-1);
 $('practice-commentary').textContent=latest?latest.minute+'′ · '+F.displayText(latest.text,m.players):'지친 선수를 바꿔보세요. 교체는 경기 시간을 넘기지 않습니다.';
 $('practice-events').innerHTML=r.events.filter(e=>!latest||e.minute!==latest.minute||e.text!==latest.text).slice(-4).reverse().map(e=>'<div><b>'+e.minute+'′</b><span>'+practiceText(F.displayText(e.text,m.players))+'</span></div>').join('');
 $('practice-sound').textContent='소리 '+(soundOn?'켜짐':'꺼짐');$('practice-sound').setAttribute('aria-pressed',soundOn);const device=practiceFeedback.snapshot();$('practice-haptic').textContent=device.supported?'진동 '+(mediaPrefs.haptics?'켜짐':'꺼짐'):'진동 미지원';$('practice-haptic').disabled=!device.supported;$('practice-haptic').setAttribute('aria-pressed',mediaPrefs.haptics);
 if(m.paused||done)renderPracticeSubs();else $('practice-subs').innerHTML='<p class="practice-sub-running">일시 정지 후 선수를 교체하세요.<br>남은 교체 '+(3-m.subs)+'명 · 실제 시간에 반영</p>';
 if(done){const justFinished=!practiceRecorded;recordPracticeResult(r);renderPracticeResult(r);if(justFinished){$('practice-result').scrollIntoView({block:'start',behavior:'instant'});$('practice-result').focus({preventScroll:true});}}else $('practice-result').hidden=true;
 drawPractice();
}
function renderPracticeSubs(){
 const m=practiceSession.match,host=$('practice-subs'),oldOut=host.querySelector('[data-practice-out]')?.value,oldIn=host.querySelector('[data-practice-in]')?.value;
 const rosterOpen=host.querySelector('details')?.open;const focusSelector=document.activeElement?.matches('[data-practice-out]')?'[data-practice-out]':document.activeElement?.matches('[data-practice-in]')?'[data-practice-in]':null;
 const players=m.lineup.map(id=>m.players[id]).sort((a,b)=>a.energy-b.energy),out=players.find(p=>p.id===oldOut)||players.find(p=>p.pos==='FW')||players[0],bench=Object.values(m.players).filter(p=>!m.lineup.includes(p.id)&&!m.out.includes(p.id)&&F.isAvailable(p)&&p.pos===out.pos),incoming=bench.find(p=>p.id===oldIn)||bench[0];
 host.innerHTML='<div class="practice-sub-title"><h3>선수 교체</h3><span>'+m.subs+'/3명 교체</span></div><div class="practice-selected-face">'+Portraits.html(out)+'<div><strong>'+practiceText(out.name)+'</strong><span>'+out.pos+' · 체력 '+Math.round(out.energy)+'</span></div></div><details class="practice-roster-options"><summary>교체 명단 펼치기</summary><label>나갈 선수<select data-practice-out aria-label="연습에서 나갈 선수" '+(m.phase==='full'?'disabled':'')+'>'+players.map(p=>'<option value="'+p.id+'" '+(p.id===out.id?'selected':'')+'>'+practiceText(p.name)+' · '+p.pos+' · 체력 '+Math.round(p.energy)+'</option>').join('')+'</select></label><label>들어올 선수<select data-practice-in aria-label="연습에서 들어올 선수" '+(!incoming||m.phase==='full'?'disabled':'')+'>'+bench.map(p=>'<option value="'+p.id+'" '+(p.id===incoming?.id?'selected':'')+'>'+practiceText(p.name)+' · 속도 '+p.speed+' · 체력 '+Math.round(p.energy)+'</option>').join('')+(!bench.length?'<option>같은 포지션의 교체 선수 없음</option>':'')+'</select></label></details><button class="secondary" data-practice="sub" '+(!incoming||m.subs>=3||m.phase==='full'?'disabled':'')+'>'+practiceText(incoming?.name||'교체 선수 없음')+' 투입 · '+m.minute+'분</button>';
 if(rosterOpen)host.querySelector('details').open=true;if(focusSelector)host.querySelector(focusSelector)?.focus();
}
function practicePreview(m,tactic){const rating=F.ratings({...m,tactic}),remaining=90-m.minute,costs=m.lineup.map(id=>{const p=m.players[id],per90=35*(1+(50-p.endurance)/250)+(tactic==='press'?8:0);return Math.min(p.energy,per90*remaining/90);});return {chances:[rating.ourRate*remaining,rating.oppRate*remaining],averageCost:costs.reduce((a,b)=>a+b,0)/costs.length};}
function pausePractice(){if(!practiceSession)return;stopPracticeMotion();practiceSession.match.paused=true;practiceClock.reset();}
function runPracticeAction(action){
 if(!practiceSession)return;const m=practiceSession.match;$('practice-error').hidden=true;
 try{if(action==='close'){closePractice();return;}if(action==='play'){if(m.phase==='full'){restartPractice(practiceSession.id);return;}if(practicePlaying())pausePractice();else{m.paused=false;practiceMotionAt=performance.now();practiceClock.reset();practiceFeedback.play('kickoff');}}else if(action==='five'){pausePractice();const events=MatchFlow.advanceFive(m,{coachPause65:false});presentPracticeEvents(events);practiceClock.reset();}else if(action==='sub'){pausePractice();const change=F.swap(m,$('practice-subs').querySelector('[data-practice-out]').value,$('practice-subs').querySelector('[data-practice-in]').value);practiceLastEvent=m.logs.at(-1);practiceEventAt=performance.now();practiceFeedback.play('sub');showPracticeImpact('선수 교체',change.in.name+' IN · '+change.out.name+' OUT','sub');}else if(action==='sound'){soundOn=!soundOn;$('sound').textContent=soundOn?'소리 켜짐':'소리 켜기';$('sound').setAttribute('aria-pressed',soundOn);if(soundOn)tone('preview');}else if(action==='haptic'){mediaPrefs.haptics=!mediaPrefs.haptics;practiceFeedback.setEnabled(mediaPrefs.haptics);matchFeedback.setEnabled(mediaPrefs.haptics);if(mediaPrefs.haptics)practiceFeedback.play('preview');save();renderFeedbackControls();}renderPractice();if(action==='play'&&m.phase!=='full')$('practice-play').focus();}
 catch(error){$('practice-error').textContent=error.message;$('practice-error').hidden=false;}
}
function restartPractice(id){pausePractice();practiceSession=Practice.create(id);practiceRecorded=false;practiceLastEvent=null;practiceElapsed=0;practiceClock.reset();$('practice-impact').hidden=true;$('practice-subs').innerHTML='';renderPractice();$('practice-title').scrollIntoView({block:'start',behavior:'instant'});$('practice-title').focus({preventScroll:true});}
function presentPracticeEvents(events){const event=[...events].reverse().find(e=>e.type==='goal')||[...events].reverse().find(e=>['chance','shot'].includes(e.type));if(event){practiceLastEvent=event;practiceEventAt=performance.now();if(event.type==='goal'){const own=event.team===0,name=own?practiceSession.match.players[event.scorerId]?.name||S.club(S.own).short:S.displayText(practiceSession.match.opponentName);showPracticeImpact(own?'GOAL!':'다시 집중!',name,own?'goal':'concede');practiceFeedback.play(own?'goal':'concede');if(soundOn)tone(own?'goal':'concede');}}if(practiceSession.match.phase==='full')practiceFeedback.play('fulltime');}
function showPracticeImpact(title,name,kind){const el=$('practice-impact');el.dataset.kind=kind;el.innerHTML='<strong>'+practiceText(title)+'</strong><span>'+practiceText(name)+'</span>';el.hidden=false;el.dataset.until=String(performance.now()+3200);}
function recordPracticeResult(r){if(practiceRecorded)return;practiceRecorded=true;const m=practiceSession.match,row={id:r.id,startMinute:r.startMinute,startScore:[...r.startScore],score:[...r.score],chances:[...r.chances],shots:[...r.shots],subs:r.subsUsed,tactic:m.tactic,changes:r.decisions.filter(d=>d.type==='tactic').length};practiceHistory[r.id]=[row,...practiceHistory[r.id]].slice(0,3);try{localStorage.setItem('win-again-touchline-v17',JSON.stringify(practiceHistory));}catch{}}
function loadPracticeHistory(){const history={comeback:[],protect:[]};try{const data=JSON.parse(localStorage.getItem('win-again-touchline-v17'));for(const id of Object.keys(history)){if(!Array.isArray(data?.[id]))continue;const expected=Practice.create(id),duration=90-expected.startMinute;history[id]=data[id].filter(r=>r?.id===id&&r.startMinute===expected.startMinute&&['startScore','score','chances','shots'].every(k=>Array.isArray(r[k])&&r[k].length===2&&r[k].every(n=>Number.isInteger(n)&&n>=0&&n<=90))&&r.startScore.every((n,i)=>n===expected.startScore[i])&&r.score.every((n,i)=>n>=r.startScore[i]&&n-r.startScore[i]<=r.shots[i]&&r.shots[i]<=r.chances[i]&&r.chances[i]<=duration)&&Number.isInteger(r.subs)&&r.subs>=0&&r.subs<=3&&Number.isInteger(r.changes)&&r.changes>=0&&r.changes<=100&&Object.hasOwn(practiceLabels,r.tactic)).slice(0,3);}}catch{}return history;}
function renderPracticeResult(r){
 const m=practiceSession.match,host=$('practice-result'),previous=practiceHistory[r.id][1];host.hidden=false;
 const swaps=r.decisions.filter(d=>d.type==='sub'),tactics=r.decisions.filter(d=>d.type==='tactic'),played=r.players.filter(p=>p.minutes>0),average=played.length?played.reduce((n,p)=>n+p.energySpent,0)/played.length:0;
 host.innerHTML='<div class="practice-result-heading"><h2>'+(r.objectiveAchieved?'연습 결과 · 목표 달성':'연습 결과')+'</h2><p>'+r.startMinute+'분 '+r.startScore.join(' : ')+' → 90분 '+r.score.join(' : ')+' · '+(r.objectiveAchieved?'연습 목표 달성':'연습 목표 미달성')+'</p></div><div class="practice-result-stats"><div><span>남은 시간의 공격 기회</span><strong>'+r.chances.join(' : ')+'</strong></div><div><span>남은 시간의 슈팅</span><strong>'+r.shots.join(' : ')+'</strong></div><div><span>선수 평균 체력 소모</span><strong>−'+average.toFixed(1)+'</strong></div></div><div class="practice-decision-log"><h3>내가 내린 지시</h3>'+ (tactics.length?tactics.map(d=>'<p><b>'+d.minute+'분</b> '+practiceText(practiceLabels[d.from]||d.from)+' → '+practiceText(practiceLabels[d.to]||d.to)+'</p>').join(''):'<p>균형 지시를 유지했습니다.</p>')+swaps.map(d=>'<p><b>'+d.minute+'분</b> '+practiceText(m.players[d.out].name)+' → '+practiceText(m.players[d.in].name)+' · 연습 중 '+(r.players.find(p=>p.id===d.in)?.minutes||0)+'분 출전</p>').join('')+'</div>'+(previous?'<div class="practice-comparison"><h3>같은 상황, 직전 시도와 비교</h3><div class="table-wrap"><table><thead><tr><th>시도</th><th>최종 점수</th><th>기회</th><th>슈팅</th><th>교체</th></tr></thead><tbody><tr><th>이번</th><td>'+r.score.join(' : ')+'</td><td>'+r.chances.join(' : ')+'</td><td>'+r.shots.join(' : ')+'</td><td>'+r.subsUsed+'명</td></tr><tr><th>직전</th><td>'+previous.score.join(' : ')+'</td><td>'+previous.chances.join(' : ')+'</td><td>'+previous.shots.join(' : ')+'</td><td>'+previous.subs+'명</td></tr></tbody></table></div></div>':'')+'<p class="practice-result-note">전술은 기회와 체력 소모를 바꿉니다. 승패에는 우연도 작용합니다. 재도전은 같은 선수·점수·상대·난수 조건에서 시작합니다.</p><div class="practice-result-actions"><button class="primary" data-practice="retry">같은 조건으로 다시 연습</button><button class="secondary" data-practice="close">내 구단에서 이어가기</button></div>';
}
function drawPractice(){
 if(!practiceSession||!$('practice-dialog').open)return;const canvas=$('practice-field'),box=canvas.getBoundingClientRect(),w=box.width,h=box.height;if(w<1||h<1)return;const dpr=Math.min(devicePixelRatio||1,2);if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);}const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);
 ctx.fillStyle='#123d31';ctx.fillRect(0,0,w,h);for(let i=0;i<10;i++){ctx.fillStyle=i%2?'rgba(178,236,144,.025)':'rgba(0,0,0,.04)';ctx.fillRect(0,h*i/10,w,h/10);}ctx.strokeStyle='rgba(215,240,220,.28)';ctx.lineWidth=1.5;const pad=18,x1=pad,y1=pad,x2=w-pad,y2=h-pad;ctx.strokeRect(x1,y1,x2-x1,y2-y1);ctx.beginPath();ctx.moveTo(x1,h/2);ctx.lineTo(x2,h/2);ctx.stroke();ctx.beginPath();ctx.arc(w/2,h/2,w*.12,0,Math.PI*2);ctx.stroke();for(const y of [y1,y2-h*.16])ctx.strokeRect(w*.27,y,w*.46,h*.16);for(const y of [y1,y2-7]){ctx.fillStyle='rgba(238,249,232,.2)';ctx.fillRect(w*.39,y,w*.22,7);}
 const elapsed=practiceElapsed+(practicePlaying()?performance.now()-practiceMotionAt:0),frame=Movement.frame({match:practiceSession.match,elapsedMs:elapsed,event:practiceLastEvent,eventAgeMs:performance.now()-practiceEventAt,motion:motionEnabled()});
 const px=p=>({x:p.x/100*(w-2*pad)+pad,y:p.y/100*(h-2*pad)+pad});for(const [side,color] of [[frame.opponent,'#d7dbe1'],[frame.own,'#df2638']])for(const p of side){const q=px(p);ctx.shadowColor='rgba(0,0,0,.25)';ctx.shadowBlur=3;ctx.fillStyle=color;ctx.beginPath();ctx.arc(q.x,q.y,11,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle=color==='#df2638'?'#fff':'#15171d';ctx.font='bold 9px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(String(p.no),q.x,q.y);}
 const ball=px(frame.ball);ctx.shadowColor='rgba(255,255,255,.5)';ctx.shadowBlur=10;ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(ball.x,ball.y,4.5,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;const impact=$('practice-impact');if(!impact.hidden&&performance.now()>Number(impact.dataset.until))impact.hidden=true;
}
document.getElementById('practice-dialog').addEventListener('click',e=>{const action=e.target.closest('[data-practice]'),tactic=e.target.closest('[data-practice-tactic]'),scenario=e.target.closest('[data-practice-scenario]');if(scenario){restartPractice(scenario.dataset.practiceScenario);return;}if(tactic&&practiceSession){pausePractice();try{F.setTactic(practiceSession.match,tactic.dataset.practiceTactic);renderPractice();}catch(error){$('practice-error').textContent=error.message;$('practice-error').hidden=false;}return;}if(action){if(action.dataset.practice==='retry')restartPractice(practiceSession.id);else runPracticeAction(action.dataset.practice);}});
document.getElementById('practice-dialog').addEventListener('change',e=>{if(e.target.matches('[data-practice-out]'))renderPracticeSubs();});
document.getElementById('practice-dialog').addEventListener('close',cleanupPractice);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&practiceSession){pausePractice();practiceFeedback?.cancel();renderPractice();}});
document.addEventListener('click',e=>{if(e.target.closest('[data-open-practice]'))openPractice('comeback');});
